exec 2>>/run/bsl-print.log; s=/usr/lib/breadstick/bsl-print-server; [ -x "$s" ] || exit 3; was=; for u in cups.socket cups.path cups.service; do systemctl -q is-active "$u" 2>/dev/null && was="$was $u"; done; [ -n "$was" ] && systemctl stop $was; mkdir -p /run/cups /tmp/.bsl-print && chmod 1777 /tmp/.bsl-print; rm -f /run/cups/cups.sock; "$s" </dev/null >/dev/null 2>>/run/bsl-print.log & k=$!; i=0; while [ ! -S /run/cups/.cupsd.sock ] && [ $i -lt 100 ] && kill -0 $k 2>/dev/null; do sleep 0.1; i=$((i+1)); done; ln -sfn .cupsd.sock /run/cups/cups.sock; end() { kill $k 2>/dev/null; rm -f /run/cups/cups.sock; [ -n "$was" ] && systemctl start $was; exit 0; }; trap end HUP TERM; while kill -0 $k 2>/dev/null; do for j in /tmp/.bsl-print/*.job; do [ -f "$j" ] && [ ! -L "$j" ] || continue; b=${j%.job}; n=${b##*/}; if [ -f "$b.pdf" ] && [ ! -L "$b.pdf" ]; then printf 'JOB %s %s %s\n' "$n" "$(wc -c < "$j")" "$(wc -c < "$b.pdf")"; cat "$j" "$b.pdf"; fi; rm -f "$j" "$b.pdf"; done; sleep 1; done; end
